mapper.select:
select * from orders

  and status = #{status}
  and number = #{number}
  and phone = #{phone}
  and user_id = #{userId}
  and delivery_time >= #{beginTime}
  and delivery_time <= #{endTime}

order by order_time desc

select ifnull(sum(if(status = 5, amount, 0)), 0) as turnover,
       ifnull(sum(if(status = 5, 1, 0)), 0)      as validOrderCount,
       count(*)                                  as totalOrderCount
from orders
where order_time >= #{begin}
  and order_time < #{end}
